class Solution:
    def maxXorSubsequence(self, nums: List[int]) -> int:
        # Linear basis for maximum exclusive-or sum
        basis = [0] * 32
        for x in nums:
            val = x
            for i in range(31, -1, -1):
                if (val >> i) & 1:
                    if not basis[i]:
                        basis[i] = val
                        break
                    val ^= basis[i]

        max_xor = 0
        for i in range(31, -1, -1):
            if (max_xor ^ basis[i]) > max_xor:
                max_xor ^= basis[i]

        return max_xor
