#include <vector>
#include <algorithm>

class Solution {
public:
    int maxXorSubsequence(std::vector<int>& nums) {
        std::vector<int> basis(32, 0);
        for (int x : nums) {
            int val = x;
            for (int i = 31; i >= 0; --i) {
                if ((val >> i) & 1) {
                    if (!basis[i]) {
                        basis[i] = val;
                        break;
                    }
                    val ^= basis[i];
                }
            }
        }
        int max_xor = 0;
        for (int i = 31; i >= 0; --i) {
            if ((max_xor ^ basis[i]) > max_xor) {
                max_xor ^= basis[i];
            }
        }
        return max_xor;
    }
};

class Solution {
    public int maxXorSubsequence(int[] nums) {
        int[] basis = new int[32];
        for (int x : nums) {
            int val = x;
            for (int i = 31; i >= 0; i--) {
                if (((val >> i) & 1) == 1) {
                    if (basis[i] == 0) {
                        basis[i] = val;
                        break;
                    }
                    val ^= basis[i];
                }
            }
        }
        int maxXor = 0;
        for (int i = 31; i >= 0; i--) {
            if ((maxXor ^ basis[i]) > maxXor) {
                maxXor ^= basis[i];
            }
        }
        return maxXor;
    }
}

